from __future__ import annotations
from collections.abc import Iterable
import os
from prometheus_client import CollectorRegistry,Counter,GCCollector,Gauge,Histogram,PlatformCollector,ProcessCollector

registry=CollectorRegistry(auto_describe=True)
if os.name != "nt":ProcessCollector(registry=registry)
PlatformCollector(registry=registry);GCCollector(registry=registry)
_LAT=(.005,.01,.025,.05,.1,.25,.5,1,2.5,5,10);_RUN=(.5,1,2,5,10,20,30,60,120,300);_ERR=(.001,.0025,.005,.01,.02,.05,.1,.2,.5);_LAG=(.001,.005,.01,.025,.05,.1,.25,.5,1)
METHODS=frozenset({"GET","POST","DELETE","PUT","PATCH","HEAD","OPTIONS"});AUTH_REASONS=frozenset({"missing_key","invalid_key"});RATE_SCOPES=frozenset({"key","ip","auth_fail"});DENY_REASONS=frozenset({"not_owner","quota","queue_full"});WS_REASONS=frozenset({"origin","ticket","revoked","limit","not_found"});RUN_KINDS=frozenset({"simulation","benchmark"});RUN_POLICIES=frozenset({"static_c","static_o","adaptive","all"});RUN_STATUSES=frozenset({"done","error","timeout"});LOAD_RESULTS=frozenset({"ok","retrained","failed"})
AUDIT_KINDS=frozenset({"auth.fail","auth.throttled","ratelimit.key","ratelimit.ip","key.create","key.revoke","run.create","benchmark.create","run.denied","ws.connect","ws.deny","model.verify_fail","model.retrained","startup","config.invalid"})
LINK_IDS=frozenset({"A-B","B-C","C-D","D-E","E-F","A-F","B-E","C-F","A-C"})
def bounded(value:object,allowed:Iterable[str],default:str="other")->str:return value if isinstance(value,str) and value in allowed else default
build_info=Gauge("eo_build_info","Build identity",["version","env"],registry=registry)
http_requests=Counter("eo_http_requests_total","HTTP requests",["method","route","status_class"],registry=registry)
http_duration=Histogram("eo_http_request_duration_seconds","HTTP request latency",["method","route"],buckets=_LAT,registry=registry)
http_in_flight=Gauge("eo_http_in_flight","In-flight HTTP requests",registry=registry);loop_lag=Histogram("eo_event_loop_lag_seconds","Event loop scheduling lag",buckets=_LAG,registry=registry)
runs_total=Counter("eo_runs_total","Finished runs",["kind","policy","status"],registry=registry);run_duration=Histogram("eo_run_duration_seconds","Run wall time",["kind","policy"],buckets=_RUN,registry=registry)
runs_active=Gauge("eo_runs_active","Runs by state",["state"],registry=registry);queue_depth=Gauge("eo_queue_depth","Runs waiting for a worker",registry=registry);queue_capacity=Gauge("eo_queue_capacity","Configured queue capacity",registry=registry);runs_stored=Gauge("eo_runs_stored","Stored run records",registry=registry)
sim_steps=Counter("eo_sim_steps_total","Simulation steps",["policy"],registry=registry);sim_requests=Counter("eo_sim_requests_total","Entanglement requests",["policy","outcome"],registry=registry);sim_reroutes=Counter("eo_sim_reroutes_total","Reroutes",["policy"],registry=registry);sim_sla_violations=Counter("eo_sim_sla_violations_total","SLA-violating allocation-steps",["policy"],registry=registry);sim_useful_pairs=Counter("eo_sim_useful_pairs_total","SLA-satisfied pairs",["policy"],registry=registry);sim_raw_pairs=Counter("eo_sim_raw_pairs_total","All delivered pairs",["policy"],registry=registry);sim_active=Gauge("eo_sim_active_allocations","Active allocations",["policy"],registry=registry);sim_sla_efficiency=Gauge("eo_sim_sla_efficiency","Useful/raw pairs of latest finished run",["policy"],registry=registry)
benchmark_improvement=Gauge("eo_benchmark_improvement_pct","Adaptive vs baseline (%)",["baseline"],registry=registry);link_fidelity=Gauge("eo_link_fidelity","Single-link fidelity",["policy","link_id","band"],registry=registry);link_utilization=Gauge("eo_link_utilization","Link channel utilization",["policy","link_id"],registry=registry)
predictor_mae=Gauge("eo_predictor_mae","EWMA absolute Werner error",registry=registry);predictor_abs_error=Histogram("eo_predictor_abs_error","Absolute Werner error",buckets=_ERR,registry=registry);predictor_oor=Gauge("eo_predictor_out_of_range_ratio","Out-of-training-range feature ratio",registry=registry);predictor_loads=Counter("eo_predictor_loads_total","Model load outcomes",["result"],registry=registry)
auth_failures=Counter("eo_auth_failures_total","Failed authentications",["reason"],registry=registry);rate_limited=Counter("eo_rate_limited_total","Rate-limit rejections",["scope"],registry=registry);run_denied=Counter("eo_run_denied_total","Denied run access/creation",["reason"],registry=registry);ws_connections=Gauge("eo_ws_connections","Open WebSocket connections",registry=registry);ws_denied=Counter("eo_ws_denied_total","WebSocket denials",["reason"],registry=registry);model_verify_failures=Counter("eo_model_verify_failures_total","Model signature failures",registry=registry);audit_events=Counter("eo_audit_events_total","Audit events",["kind"],registry=registry);audit_chain_ok=Gauge("eo_audit_chain_ok","Audit chain verified (1/0, -1 unknown)",registry=registry);audit_entries=Gauge("eo_audit_entries","Audit log entries at last verification",registry=registry)
audit_chain_ok.set(-1)
